function statsRoutes(db) {
  const router = Router();
  router.use(requireAuth);
  router.get("/", async (req, res) => {
    const user = req.user;
    const everyone = can(user, "activity:read-all");
    const today = (/* @__PURE__ */ new Date()).toISOString().slice(0, 10);
    const byStatus = Object.fromEntries(PROJECT_STATUSES.map((s) => [s, 0]));
    for (const row of await db.all("SELECT status, COUNT(*)::int AS n FROM projects GROUP BY status")) {
      byStatus[row.status] = row.n;
    }
    const total = Object.values(byStatus).reduce((a, b) => a + b, 0);
    const overdue = (await db.get(`SELECT COUNT(*)::int AS n FROM projects WHERE due_date < ? AND status <> 'completed'`, [today]))?.n ?? 0;
    const mine = (await db.get("SELECT COUNT(*)::int AS n FROM projects WHERE owner_id = ?", [user.id]))?.n ?? 0;
    let users = null;
    if (can(user, "user:read")) {
      users = await db.get(
        `SELECT COUNT(*)::int AS total, (COUNT(*) FILTER (WHERE status = 'active'))::int AS active FROM users`
      ) ?? { total: 0, active: 0 };
    }
    const start = /* @__PURE__ */ new Date();
    start.setUTCHours(0, 0, 0, 0);
    start.setUTCDate(start.getUTCDate() - 13);
    const scopeSql = everyone ? "" : "AND actor_id = ?";
    const scopeParams = everyone ? [] : [user.id];
    const counts = new Map(
      (await db.all(
        `SELECT substr(created_at, 1, 10) AS day, COUNT(*)::int AS n FROM activity WHERE created_at >= ? ${scopeSql} GROUP BY day`,
        [start.toISOString(), ...scopeParams]
      )).map((r) => [r.day, r.n])
    );
    const activityByDay = Array.from({ length: 14 }, (_, i) => {
      const d = new Date(start.getTime() + i * 864e5).toISOString().slice(0, 10);
      return { date: d, count: counts.get(d) ?? 0 };
    });
    const recent = await db.all(
      `${SELECT} ${everyone ? "" : "WHERE actor_id = ?"} ORDER BY created_at DESC, id DESC LIMIT 6`,
      scopeParams
    );
    const stats = {
      users,
      projects: { total, byStatus, overdue, mine },
      activityByDay,
      activityScope: everyone ? "everyone" : "own",
      recent
    };
    res.json(stats);
  });
  return router;
}

